import asyncio
from starlette.websockets import WebSocket, WebSocketDisconnected, WebSocketState

async def receive_connect():
    return {\"type\": \"websocket.connect\"}

async def send(message):
    pass

async def main():
    websocket = WebSocket({\"type\": \"websocket\", \"path\": \"/\"}, receive_connect, send)
    assert issubclass(WebSocketDisconnected, RuntimeError)

    websocket.client_state = WebSocketState.DISCONNECTED
    try:
        await websocket.receive()
    except WebSocketDisconnected as exc:
        assert str(exc) == 'Cannot call \"receive\" once a disconnect message has been received.'
    else:
        raise AssertionError(\"receive did not raise\")

    websocket.application_state = WebSocketState.DISCONNECTED
    try:
        await websocket.send({\"type\": \"websocket.send\", \"text\": \"test\"})
    except WebSocketDisconnected as exc:
        assert str(exc) == 'Cannot call \"send\" once a close message has been sent.'
    else:
        raise AssertionError(\"send did not raise\")

    for method, args in ((websocket.receive_text, ()), (websocket.receive_bytes, ()), (websocket.receive_json, ())):
        try:
            await method(*args)
        except WebSocketDisconnected as exc:
            assert str(exc) == 'WebSocket is not connected. Need to call \"accept\" first.'
        else:
            raise AssertionError(f\"{method.__name__} did not raise\")

    try:
        await websocket.receive_json(mode=\"invalid\")
    except RuntimeError as exc:
        assert type(exc) is RuntimeError
        assert str(exc) == 'The \"mode\" argument should be \"text\" or \"binary\".'
    else:
        raise AssertionError(\"invalid mode did not raise\")

asyncio.run(main())
print(\"direct websocket state checks passed\")
