import asyncio

from starlette.websockets import WebSocket, WebSocketDisconnect, WebSocketDisconnected, WebSocketState

SCOPE = {\"type\": \"websocket\", \"path\": \"/\"}

async def noop_send(message):
    pass

async def unexpected_receive():
    return {\"type\": \"http.request\"}

async def peer_disconnect():
    return {\"type\": \"websocket.disconnect\", \"code\": 1001, \"reason\": \"away\"}

async def main():
    assert WebSocketDisconnected.__bases__ == (RuntimeError,)

    websocket = WebSocket(SCOPE, unexpected_receive, noop_send)
    websocket.client_state = WebSocketState.DISCONNECTED
    try:
        await websocket.receive()
    except WebSocketDisconnected as exc:
        assert str(exc) == 'Cannot call \"receive\" once a disconnect message has been received.'
    else:
        raise AssertionError(\"disconnected receive did not raise\")

    websocket.application_state = WebSocketState.DISCONNECTED
    try:
        await websocket.send({\"type\": \"websocket.send\", \"text\": \"test\"})
    except WebSocketDisconnected as exc:
        assert str(exc) == 'Cannot call \"send\" once a close message has been sent.'
    else:
        raise AssertionError(\"disconnected send did not raise\")

    for state in (WebSocketState.CONNECTING, WebSocketState.DISCONNECTED):
        websocket.application_state = state
        for method in (websocket.receive_text, websocket.receive_bytes, websocket.receive_json):
            try:
                await method()
            except WebSocketDisconnected as exc:
                assert str(exc) == 'WebSocket is not connected. Need to call \"accept\" first.'
            else:
                raise AssertionError(f\"{method.__name__} did not raise in {state}\")

    try:
        await websocket.receive_json(mode=\"invalid\")
    except RuntimeError as exc:
        assert type(exc) is RuntimeError
    else:
        raise AssertionError(\"invalid mode did not raise\")

    websocket = WebSocket(SCOPE, unexpected_receive, noop_send)
    try:
        await websocket.receive()
    except RuntimeError as exc:
        assert type(exc) is RuntimeError
    else:
        raise AssertionError(\"protocol error did not raise\")

    websocket = WebSocket(SCOPE, peer_disconnect, noop_send)
    websocket.client_state = WebSocketState.CONNECTED
    websocket.application_state = WebSocketState.CONNECTED
    try:
        await websocket.receive_text()
    except WebSocketDisconnect as exc:
        assert type(exc) is WebSocketDisconnect
        assert (exc.code, exc.reason) == (1001, \"away\")
    else:
        raise AssertionError(\"peer disconnect did not raise\")

asyncio.run(main())
print(\"all websocket exception checks passed\")
